#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite); library(ggplot2)})
`%||%` <- function(a,b) if (is.null(a)) b else a
op <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'))))
out <- op$output %||% getwd(); dir.create(out, recursive=TRUE, showWarnings=FALSE)
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(m,d='',s='Check input columns and params.json.') { write(toJSON(list(error=m,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); quit(status=1) }
tryCatch({
 if (is.null(op$input)||!file.exists(op$input)) fail('Input file not found',as.character(op$input))
 p <- if (!is.null(op$params)&&file.exists(op$params)) fromJSON(op$params,simplifyVector=FALSE) else list()
 val <- function(n,d=NULL,a=character()) { x<-p[[n]]; if(is.null(x)) for(k in a) if(!is.null(p[[k]])){x<-p[[k]];break}; if(is.null(x)) d else x }
 vec <- function(x) if(is.null(x)) character() else trimws(as.character(unlist(x)))
 num <- function(n,d,a=character()) { x<-suppressWarnings(as.numeric(unlist(val(n,d,a))[1])); if(is.na(x)) d else x }
 boo <- function(n,d=FALSE,a=character()) { x<-val(n,d,a); if(is.logical(x)) isTRUE(x[1]) else tolower(as.character(x[1]))%in%c('true','1','yes','y','on') }
 readtab <- function(f) if(tolower(tools::file_ext(f))%in%c('tsv','txt')) read.delim(f,check.names=FALSE,stringsAsFactors=FALSE) else read.csv(f,check.names=FALSE,stringsAsFactors=FALSE)
 d <- readtab(op$input); cn <- names(d); findcol <- function(x,defs=character(),req=TRUE) { z<-c(x,defs); i<-match(tolower(z),tolower(cn)); i<-i[!is.na(i)]; if(length(i)) cn[i[1]] else if(req) fail('Required column not found',paste(z,collapse=', ')) else NULL }
 mc <- findcol(val('metric_column',NULL,c('metric_col','category_column','category_col')),c('metric','category','variable','label','name'))
 mode <- tolower(as.character(val('input_mode','auto'))); gc <- findcol(val('group_column',NULL,c('group_col')),c('group','series'),FALSE); vc <- findcol(val('value_column',NULL,c('value_col')),c('value','score','estimate'),FALSE)
 if(mode=='long'||(mode=='auto'&&!is.null(gc)&&!is.null(vc))) {
   if(is.null(gc)||is.null(vc)) fail('Long input requires group_column and value_column')
   z <- data.frame(metric=as.character(d[[mc]]),group=as.character(d[[gc]]),value=suppressWarnings(as.numeric(d[[vc]])),stringsAsFactors=FALSE)
 } else {
   groups <- vec(val('group_order')); if(!length(groups)) groups <- cn[!cn%in%mc & vapply(d[setdiff(cn,mc)],function(x) any(!is.na(suppressWarnings(as.numeric(x)))),logical(1))]
   if(!length(groups)) fail('Wide input has no numeric group columns')
   z <- do.call(rbind,lapply(groups,function(g) data.frame(metric=as.character(d[[mc]]),group=g,value=suppressWarnings(as.numeric(d[[g]])),stringsAsFactors=FALSE)))
 }
 z <- z[!is.na(z$value)&nzchar(z$metric)&nzchar(z$group),,drop=FALSE]; if(!nrow(z)) fail('No valid numeric rows remain')
 inc<-vec(val('metrics_include',NULL,c('categories_include'))); exc<-vec(val('metrics_exclude',NULL,c('categories_exclude'))); if(length(inc)) z<-z[z$metric%in%inc,,drop=FALSE]; if(length(exc)) z<-z[!z$metric%in%exc,,drop=FALSE]; if(!nrow(z)) fail('No rows remain after filtering')
 metrics <- unique(z$metric); mo<-vec(val('metric_order',NULL,c('category_order'))); if(length(mo)) metrics<-unique(c(mo,metrics)); metrics<-metrics[metrics%in%unique(z$metric)]; if(boo('reverse_metrics')) metrics<-rev(metrics); z<-z[z$metric%in%metrics,,drop=FALSE]
 groups <- vec(val('group_order')); if(!length(groups)) groups<-unique(z$group); groups<-c(groups, setdiff(unique(z$group),groups)); groups<-groups[groups%in%unique(z$group)]; z$metric<-factor(z$metric,levels=metrics); z$group<-factor(z$group,levels=groups)
 raw_min<-min(z$value); raw_max<-max(z$value); normalize<-boo('normalize',FALSE); if(normalize) { method<-tolower(as.character(val('normalization','minmax'))); if(method=='zscore') z$value<-ave(z$value,z$metric,FUN=function(x) (x-mean(x))/ifelse(sd(x)==0,1,sd(x))) else { lo<-num('normalization_min',raw_min); hi<-num('normalization_max',raw_max); z$value<-(z$value-lo)/ifelse(hi==lo,1,hi-lo) } }
 lim<-unlist(val('radial_limits',NULL,c('r_limits'))); lim<-suppressWarnings(as.numeric(lim)); if(length(lim)!=2||any(!is.finite(lim))) lim<-range(z$value,finite=TRUE); if(lim[1]>lim[2]) lim<-rev(lim); if(lim[1]==lim[2]) lim<-lim+c(-.5,.5)
 breaks<-suppressWarnings(as.numeric(unlist(val('radial_breaks',NULL,c('r_breaks'))))); breaks<-breaks[is.finite(breaks)]; if(!length(breaks)) breaks<-pretty(lim,n=5); breaks<-breaks[breaks>=lim[1]&breaks<=lim[2]]
 z$hover<-paste0(as.character(z$group),' | ',as.character(z$metric),': ',formatC(z$value,format='fg',digits=5))
 ang<-2*pi*(seq_along(metrics)-1)/length(metrics)+pi/2; coords<-expand.grid(metric=metrics,group=groups,stringsAsFactors=FALSE); coords$value<-z$value[match(paste(coords$metric,coords$group),paste(as.character(z$metric),as.character(z$group)))]; coords$theta<-ang[match(coords$metric,metrics)]; coords$x<-coords$value*cos(coords$theta); coords$y<-coords$value*sin(coords$theta); coords$hover<-z$hover[match(paste(coords$metric,coords$group),paste(as.character(z$metric),as.character(z$group)))]
 pal<-unlist(val('group_colors')); if(is.null(names(pal))) pal<-character(); defaults<-scales::hue_pal()(length(groups)); names(defaults)<-groups; defaults[names(pal)]<-as.character(pal[names(pal)]); pal<-defaults
 highlight<-vec(val('highlight_groups')); hmetrics<-vec(val('highlight_metrics',NULL,c('highlight_categories'))); highlight_color<-as.character(val('highlight_color','#E69F00'))
 center<-data.frame(x=0,y=0); grid<-do.call(rbind,lapply(breaks,function(r){data.frame(x=r*cos(c(ang,ang[1])),y=r*sin(c(ang,ang[1])),kind='ring',id=r)})); spokes<-data.frame(x1=0,y1=0,x2=lim[2]*cos(ang),y2=lim[2]*sin(ang)); labs<-data.frame(metric=metrics,x=(lim[2]*1.08)*cos(ang),y=(lim[2]*1.08)*sin(ang),label=metrics)
 q<-ggplot()+coord_equal(xlim=c(-lim[2]*1.25,lim[2]*1.25),ylim=c(-lim[2]*1.25,lim[2]*1.25),expand=FALSE,clip='off')
 if(boo('grid_show',TRUE)) q<-q+geom_path(data=grid,aes(x,y,group=id),colour=val('grid_color','#D9D9D9'),linewidth=num('grid_width',.4),linetype=val('grid_linetype','solid'))+geom_segment(data=spokes,aes(x=x1,y=y1,xend=x2,yend=y2),colour=val('grid_color','#D9D9D9'),linewidth=num('grid_width',.4))
 for(g in groups) { a<-coords[coords$group==g,]; a<-rbind(a,a[1,]); q<-q+geom_polygon(data=a,aes(x,y),fill=pal[g],colour=pal[g],alpha=num('fill_alpha',.18),linewidth=num('line_width',1),show.legend=TRUE)+geom_path(data=a,aes(x,y,colour=g),linewidth=num('line_width',1),show.legend=TRUE) }
 q<-q+geom_point(data=coords,aes(x,y,colour=group),size=num('point_size',2.8),alpha=num('point_alpha',.95))+scale_colour_manual(values=pal,name=val('legend_title','Group'),drop=FALSE)+geom_text(data=labs,aes(x,y,label=label),size=num('metric_label_size',3.5),colour=val('metric_label_color','#333333'))
 if(boo('value_labels')) q<-q+geom_text(data=coords,aes(x,y,label=formatC(value,format='fg',digits=4),colour=group),size=num('value_label_size',2.6),vjust=-.8,show.legend=FALSE)
 if(length(highlight)||length(hmetrics)) { hh<-coords[(as.character(coords$group)%in%highlight)|(as.character(coords$metric)%in%hmetrics),]; if(nrow(hh)) q<-q+geom_point(data=hh,aes(x,y),colour=highlight_color,size=num('highlight_size',5),shape=21,fill=NA,stroke=num('highlight_stroke',1),show.legend=FALSE) }
 q<-q+labs(title=if(boo('title_show',TRUE))val('title','Interactive Radar Plot')else NULL,subtitle=val('subtitle'),caption=val('caption'))+theme_void(base_size=num('base_size',11),base_family=val('font_family','sans'))+theme(plot.background=element_rect(fill=val('plot_background','white'),colour=NA),legend.position=if(boo('legend_show',TRUE))val('legend_position','right')else'none',legend.title=element_text(size=num('legend_title_size',10)),legend.text=element_text(size=num('legend_text_size',9)),plot.title=element_text(size=num('title_size',16),face=val('title_face','bold'),hjust=num('title_hjust',.5),colour=val('title_color','#222222')),plot.subtitle=element_text(size=num('subtitle_size',11),colour=val('subtitle_color','#555555'),hjust=num('title_hjust',.5)),plot.caption=element_text(size=num('caption_size',9)),plot.margin=grid::unit(rep(num('margin',.5),4),'cm'))
 w<-num('width',8); h<-num('height',7); dpi<-num('dpi',300); formats<-tolower(vec(val('export_formats',c('svg','pdf','png','html')))); if('svg'%in%formats) ggsave(file.path(out,'result.svg'),q,width=w,height=h,units='in',dpi=dpi); if('pdf'%in%formats) ggsave(file.path(out,'result.pdf'),q,width=w,height=h,units='in'); if('png'%in%formats) ggsave(file.path(out,'result.png'),q,width=w,height=h,units='in',dpi=dpi)
 if(boo('interactive',TRUE)&&requireNamespace('plotly',quietly=TRUE)) { pl<-plotly::plot_ly(); for(g in groups) { a<-coords[coords$group==g,]; a<-rbind(a,a[1,]); pl<-plotly::add_trace(pl,r=a$value,theta=as.character(a$metric),type='scatterpolar',mode=if(boo('value_labels'))'lines+markers+text'else'lines+markers',fill='toself',name=g,line=list(color=pal[g],width=num('line_width',2)),fillcolor=pal[g],opacity=num('interactive_alpha',.7),marker=list(color=pal[g],size=num('interactive_marker_size',7)),text=if(boo('value_labels'))formatC(a$value,format='fg',digits=4) else a$hover,hovertext=a$hover,hoverinfo='text',textposition='top center') }; pl<-plotly::layout(pl,title=list(text=paste0(ifelse(is.null(val('title',NULL)),'',val('title','')),if(!is.null(val('subtitle',NULL)))paste0('<br><sup>',val('subtitle',''),'</sup>')else'')),polar=list(radialaxis=list(range=lim,tickvals=breaks,showgrid=boo('grid_show',TRUE),showticklabels=boo('radial_labels',TRUE)),angularaxis=list(categoryorder='array',categoryarray=metrics)),showlegend=boo('legend_show',TRUE)); pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),modeBarButtonsToAdd=if(boo('selectable',TRUE))c('lasso2d','select2d') else character(),toImageButtonOptions=list(format='png',filename='radar_plot',width=round(w*dpi),height=round(h*dpi))); htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE) } else writeLines('<html><body>Plotly is unavailable.</body></html>',file.path(out,'result.html'))
 write.csv(data.frame(metric=as.character(z$metric),group=as.character(z$group),value=z$value),file.path(out,'selected_rows.csv'),row.names=FALSE); write(toJSON(list(plugin='interactive_radar_plot',input_mode=mode,normalized=normalize,groups=groups,metrics=metrics,radial_limits=lim,radial_breaks=breaks,rows=nrow(z),outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','selected_rows.csv')),auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json')); if(file.exists(file.path(out,'error.json'))) unlink(file.path(out,'error.json')); logmsg(sprintf('Rendered %d values across %d groups and %d metrics',nrow(z),length(groups),length(metrics)))
},error=function(e) fail('Plot generation failed',conditionMessage(e)))
